final readonly class ExaminationManifestationStandAdmissionService
{
 private string $deliveries;private string $custody;private string $occupancy;private string $admissions;
 public function __construct(#[Autowire('%kernel.project_dir%')] string $root){$s=$root.'/var/imperium/offices/senate';$this->deliveries=$s.'/examination-manifestation-intake';$this->occupancy=$s.'/occupancy';$this->admissions=$s.'/examination-stand-admissions';$this->custody=$root.'/var/imperium/offices/garrison/custody';}
 public function admit(string $deliveryId,string $bindingId):array
 {
  if(!preg_match('/^examination-manifestation-delivery-[a-f0-9]{20}$/',$deliveryId))throw new \InvalidArgumentException('S186_EXAMINATION_MANIFESTATION_DELIVERY_ID_INVALID');
